/** "발병 N일째" with the onset day counted as day 1 (stored values are days since onset, 0-based). */
export const dayLabel = (daysSinceOnset: number): string => `발병 ${daysSinceOnset + 1}일째`;

export const fmtDate = (iso: string): string => {
  const d = new Date(iso);
  return `${d.getFullYear()}.${d.getMonth() + 1}.${d.getDate()}`;
};

export const fmtDateTime = (iso: string): string => {
  const d = new Date(iso);
  const z = (n: number) => String(n).padStart(2, '0');
  return `${fmtDate(iso)} ${z(d.getHours())}:${z(d.getMinutes())}`;
};

/**
 * How "affected side as a share of the healthy side" is shown (display only; stored values are unchanged).
 * Provisional bands until the pilot's same-day repeat assessments give the measurement error.
 */
export const RATIO_DISPLAY = {
  /** Up to this the affected side is shown as 100 % (as much as the healthy side, within error). */
  over: 1.25,
  /** Both sides moved less than this (mm): too small for a stable ratio. */
  tinyMm: 3,
} as const;

export interface RatioView {
  text: string;
  kind: 'pct' | 'full' | 'over' | 'small' | 'none';
  /** One sentence for details and tooltips. */
  note?: string;
}

/** `maxMm` = larger movement of the two sides in mm, when known (not for eye-closure fractions). */
export function ratioView(ratio: number | null | undefined, maxMm?: number | null): RatioView {
  if (ratio == null || !Number.isFinite(ratio)) return { text: '비교 불가', kind: 'none' };
  if (maxMm != null && maxMm < RATIO_DISPLAY.tinyMm)
    return {
      text: '움직임 작음',
      kind: 'small',
      note: `양쪽 모두 ${RATIO_DISPLAY.tinyMm} mm 미만으로 움직여 비율이 불안정합니다(참고값 ${Math.round(ratio * 100)}%). 동작을 조금 더 크게 해 다시 재 보세요.`,
    };
  if (ratio > RATIO_DISPLAY.over)
    return {
      text: '100% 넘음',
      kind: 'over',
      note: `마비 쪽이 건강한 쪽보다 크게 움직였습니다(${Math.round(ratio * 100)}%). 과한 움직임(긴장·연합운동)이거나 측정 오차일 수 있어 의료진과 확인하세요.`,
    };
  if (ratio >= 1) return { text: '100%', kind: 'full', note: `양쪽 비슷합니다(측정값 ${Math.round(ratio * 100)}%, 오차 범위 안).` };
  return { text: `${Math.round(Math.max(0, ratio) * 100)}%`, kind: 'pct' };
}

/** Larger of the two sides' movement in mm, or null. */
export const maxMm = (mm: { left: number; right: number } | null | undefined): number | null => (mm ? Math.max(mm.left, mm.right) : null);
