import { useState } from 'preact/hooks';
import { ImportError, importCount, planImport, subjectDiff, type ImportPlan, type ImportSubject, type SealedPart } from '../../data/import';
import { actions, getState, useApp } from '../../data/store';
import { Icon } from '../icons';
import { ETIOLOGY_LABEL, SIDE_LABEL, fmtDateTime } from '../labels';
import { Notice } from './common';

const FIELD: Record<keyof ImportSubject, [string, (s: ImportSubject) => string]> = {
  affectedSide: ['마비 쪽', (s) => SIDE_LABEL[s.affectedSide]],
  onsetDate: ['발병일', (s) => s.onsetDate],
  etiology: ['원인', (s) => ETIOLOGY_LABEL[s.etiology]],
  birthYear: ['출생 연도', (s) => (s.birthYear ? String(s.birthYear) : '없음')],
};

function sealedLine(name: string, p: SealedPart<unknown>) {
  const extra = [
    p.same > 0 && `이미 있음 ${p.same}건`,
    p.conflict > 0 && `같은 번호·다른 내용 ${p.conflict}건(이 폰 기록 유지)`,
    p.invalid > 0 && `봉인 확인 실패 ${p.invalid}건(가져오지 않음)`,
  ].filter(Boolean);
  return (
    <li>
      {name}: 새로 <b>{p.add.length}건</b>
      {extra.length > 0 && <span class="muted"> · {extra.join(' · ')}</span>}
    </li>
  );
}

/** Settings list item: restore records from a JSON export (another phone, browser or app address), after a preview. */
export function ImportBackup() {
  const { profile, sessions } = useApp();
  const [plan, setPlan] = useState<ImportPlan | null>(null);
  const [adopt, setAdopt] = useState(false);
  const [msg, setMsg] = useState<{ tone: 'good' | 'danger'; text: string } | null>(null);
  const [busy, setBusy] = useState(false);
  if (!profile) return null;
  const diff = plan ? subjectDiff(plan, profile) : [];
  const n = plan ? importCount(plan) : 0;

  const choose = async (input: HTMLInputElement) => {
    const file = input.files?.[0];
    input.value = '';
    if (!file) return;
    setMsg(null);
    setBusy(true);
    try {
      const p = await planImport(await file.text(), getState());
      setPlan(p);
      setAdopt(sessions.length === 0 && subjectDiff(p, profile).length > 0);
    } catch (e) {
      setPlan(null);
      setMsg({ tone: 'danger', text: e instanceof ImportError ? e.message : '파일을 읽지 못했습니다.' });
    } finally {
      setBusy(false);
    }
  };

  const run = async () => {
    if (!plan) return;
    setBusy(true);
    try {
      await actions.importBackup(plan, adopt && diff.length > 0);
      setMsg({ tone: 'good', text: `${n}건을 가져왔습니다.${adopt && diff.length > 0 ? ' 내 정보도 파일 기준으로 바꿨습니다.' : ''}` });
      setPlan(null);
    } catch {
      setMsg({ tone: 'danger', text: '가져오는 중 문제가 생겼습니다. 일부만 들어갔을 수 있으니 같은 파일로 한 번 더 가져오세요(중복은 건너뜁니다).' });
    } finally {
      setBusy(false);
    }
  };

  return (
    <>
      <label class="list-item" style={{ cursor: busy ? 'progress' : 'pointer' }}>
        <Icon name="upload" />
        <div class="grow">
          기록 가져오기 (JSON)
          <div class="xsmall muted">다른 폰·브라우저·주소에서 내보낸 파일, 봉인 확인 후 합치기</div>
        </div>
        <input
          type="file"
          accept="application/json,.json"
          disabled={busy}
          style={{ display: 'none' }}
          onChange={(e) => choose(e.target as HTMLInputElement)}
        />
      </label>
      {(plan || msg) && (
        <div style={{ borderTop: '1px solid var(--border)', padding: '12px 2px' }}>
          {msg && (
            <Notice tone={msg.tone}>
              <span class="small">{msg.text}</span>
            </Notice>
          )}
          {plan && (
            <>
              <div class="small" style={{ fontWeight: 600 }}>
                백업 파일{plan.exportedAt ? ` · ${fmtDateTime(plan.exportedAt)} 내보냄` : ''}
                {plan.appVersion ? ` · 앱 v${plan.appVersion}` : ''}
              </div>
              <ul class="small" style={{ margin: '6px 0', paddingLeft: '18px' }}>
                {sealedLine('평가 기록', plan.sessions)}
                {sealedLine('연합운동 기록', plan.synk)}
                <li>
                  임상가 평가 새로 <b>{plan.ratings.add.length}건</b>, 운동 기록 새로 <b>{plan.rehab.add.length}건</b>
                </li>
              </ul>
              {profile.demo ? (
                <Notice tone="danger">
                  <span class="small">
                    지금은 체험용(데모) 프로필이라 가져올 수 없습니다. 아래 ‘모든 데이터 삭제’로 체험 기록을 지우고 내 프로필을 만든 뒤
                    가져오세요.
                  </span>
                </Notice>
              ) : (
                diff.length > 0 && (
                  <>
                    <Notice tone="warn">
                      <span class="small">
                        파일의 환자 정보가 지금 내 정보와 다릅니다:{' '}
                        {diff.map((k) => `${FIELD[k][0]} ${FIELD[k][1](plan.subject!)}(지금 ${FIELD[k][1](profile)})`).join(', ')}. 다른 사람의
                        기록이면 가져오지 마세요.
                      </span>
                    </Notice>
                    <label class="check small" style={{ padding: '4px 0' }}>
                      <input type="checkbox" checked={adopt} onChange={(e) => setAdopt((e.target as HTMLInputElement).checked)} />
                      <span>내 정보를 파일 기준으로 바꾸기 (이전 기록은 기록 당시 설정 유지)</span>
                    </label>
                  </>
                )
              )}
              <p class="xsmall muted" style={{ margin: '4px 0 8px' }}>
                이 폰에 있는 기록은 바뀌지 않고, 없는 기록만 더합니다. 사진은 백업 파일에 들어 있지 않아 옮겨지지 않습니다.
              </p>
              <div class="row">
                <button class="btn grow" disabled={busy} onClick={() => setPlan(null)}>
                  취소
                </button>
                <button class="btn primary grow" disabled={busy || n === 0 || !!profile.demo} onClick={run}>
                  {n === 0 ? '새로 가져올 기록 없음' : busy ? '가져오는 중…' : `${n}건 가져오기`}
                </button>
              </div>
            </>
          )}
        </div>
      )}
    </>
  );
}
