/**
 * FPA-SYNK: synkinesis finder over a 10-expression sequence.
 *
 * For every expression, the movement of each face region is measured on both
 * sides against the rest reference (same alignment as FPA-GEOM). A region that
 * is NOT the target of the expression and moves more on the affected side than
 * on the healthy side is reported as involuntary co-movement (synkinesis),
 * e.g. the eye narrowing while saying "오". Pure and deterministic.
 *
 * 0.2.0: the upper lip is its own region (lifting it during a tight eye closure is synkinesis, the cheek is
 * not); below the threshold, a co-movement of at least half of it that also rises and falls with the
 * expression on the affected side (frame correlation, more than on the healthy side) is reported as mild.
 */
import { AGGREGATION, alignTo, gate, medianShape, selectPeakFrames } from './analyze';
import { dist, faceFrame, toFaceCoords, toPixels } from './geometry';
import { SIDE, otherSide } from './landmarks';
import { browLevel, eyeAperture, irisDiameter, midfaceLevel, mouthCorner } from './measures';
import { DEFAULT_QUALITY, type QualityThresholds } from './quality';
import { mean, median } from './stats';
import type { FrameObservation, Side, Vec2 } from './types';

export const COUPLING_ID = 'FPA-SYNK';
export const COUPLING_VERSION = '0.2.1';

export const COUPLING_EXPRESSIONS = ['brow', 'eyeGentle', 'eyeTight', 'smileClosed', 'pucker', 'oh', 'oo', 'frown', 'ee'] as const;
export type CouplingExpression = (typeof COUPLING_EXPRESSIONS)[number];
export type CouplingRegion = 'brow' | 'eye' | 'midface' | 'upperLip' | 'mouth';
export const COUPLING_REGIONS: readonly CouplingRegion[] = ['brow', 'eye', 'midface', 'upperLip', 'mouth'];

/** Regions each expression is meant to move (not counted as synkinesis). */
export const TARGET_REGIONS: Record<CouplingExpression, readonly CouplingRegion[]> = {
  brow: ['brow'],
  eyeGentle: ['eye'],
  eyeTight: ['eye', 'brow', 'midface'],
  smileClosed: ['mouth', 'midface', 'upperLip'],
  pucker: ['mouth', 'upperLip'],
  oh: ['mouth', 'upperLip'],
  oo: ['mouth', 'upperLip'],
  frown: ['brow', 'eye'],
  ee: ['mouth', 'midface', 'upperLip'],
};

/**
 * Minimum affected-minus-healthy movement to report co-movement:
 * eye = fraction of the rest aperture, others = face units (inter-eye distance ≈ 62 mm).
 */
export const COUPLING_THRESHOLDS: Record<CouplingRegion, number> = { brow: 0.03, eye: 0.1, midface: 0.03, upperLip: 0.025, mouth: 0.035 };

/** Mild co-movement: excess ≥ this share of the threshold, plus the frame correlation below. */
export const MILD = { fraction: 0.5, minSync: 0.5, minSyncLead: 0.2 } as const;

type Face = readonly Vec2[];

/** Movement of each region against rest (≥ 0): eye = narrowing fraction, others = displacement. */
function regionMovement(rest: Face, expr: Face, side: Side): Record<CouplingRegion, number> {
  return {
    brow: Math.abs(browLevel(rest, side) - browLevel(expr, side)),
    eye: Math.max(0, 1 - eyeAperture(expr, side) / eyeAperture(rest, side)),
    midface: Math.abs(midfaceLevel(rest, side) - midfaceLevel(expr, side)),
    upperLip: Math.abs(mean(SIDE[side].upperLip.map((i) => rest[i]!.y - expr[i]!.y))),
    mouth: dist(mouthCorner(expr, side), mouthCorner(rest, side)),
  };
}

export interface CouplingCell {
  affected: number;
  healthy: number;
  /** affected − healthy (positive = the affected side moves more). */
  excess: number;
  target: boolean;
  /** Non-target region moving more on the affected side than the threshold. */
  flagged: boolean;
  /** Below the threshold but at least MILD.fraction of it, moving with the expression (0.2.0+). */
  mild?: boolean;
  /** Correlation of this region's movement with the expression over the recorded frames, per side (0.2.0+). */
  sync?: { affected: number; healthy: number };
}

export interface CouplingFinding {
  expression: CouplingExpression;
  region: CouplingRegion;
  excess: number;
  /** excess / threshold (≥ 1). */
  severity: number;
}

export interface CouplingResult {
  algorithm: { id: string; version: string };
  status: 'complete' | 'incomplete' | 'failed';
  affectedSide: Side;
  mmPerUnit: number | null;
  /** Per expression (measured ones only): per-region movement per side. */
  cells: Partial<Record<CouplingExpression, Record<CouplingRegion, CouplingCell>>>;
  /** Target-movement ratio affected / healthy per expression (weakness, for context). */
  targetRatio: Partial<Record<CouplingExpression, number>>;
  missing: CouplingExpression[];
  findings: CouplingFinding[];
  /** Mild (suspected) co-movements, not counted in `findings` (0.2.0+; absent in older records). */
  mild?: CouplingFinding[];
}

export interface CouplingInput {
  affectedSide: Side;
  rest: readonly FrameObservation[];
  expressions: Partial<Record<CouplingExpression, readonly FrameObservation[]>>;
  /** Defaults to the app's quality gate (the bench can relax it for research). */
  quality?: QualityThresholds;
}

export function analyzeCoupling(input: CouplingInput): CouplingResult {
  const aff = input.affectedSide;
  const hea = otherSide(aff);
  const result: CouplingResult = {
    algorithm: { id: COUPLING_ID, version: COUPLING_VERSION },
    status: 'failed',
    affectedSide: aff,
    mmPerUnit: null,
    cells: {},
    targetRatio: {},
    missing: [],
    findings: [],
    mild: [],
  };
  const min = AGGREGATION.minValidFrames.video;
  const restGate = gate(input.rest, input.quality ?? DEFAULT_QUALITY);
  if (restGate.valid.length < min) {
    result.missing = [...COUPLING_EXPRESSIONS];
    return result;
  }
  const restList = restGate.valid.map((v) => toPixels(v.obs));
  const restPx = medianShape(restList.map((px) => alignTo(px, restList[0]!).pts));
  const frame = faceFrame(restPx);
  const restF = toFaceCoords(frame, restPx);
  if (restF.length >= 478) {
    const irisD = (irisDiameter(restF, 'left') + irisDiameter(restF, 'right')) / 2;
    if (irisD >= 0.12 && irisD <= 0.3) result.mmPerUnit = AGGREGATION.irisDiameterMm / irisD;
  }

  for (const e of COUPLING_EXPRESSIONS) {
    const g = gate(input.expressions[e] ?? [], input.quality ?? DEFAULT_QUALITY);
    if (g.valid.length < min) {
      result.missing.push(e);
      continue;
    }
    const targets = TARGET_REGIONS[e];
    const per = g.valid.map(({ obs }) => {
      const F = toFaceCoords(frame, alignTo(toPixels(obs), restPx).pts);
      const a = regionMovement(restF, F, aff);
      const h = regionMovement(restF, F, hea);
      // Peak of the intended movement, side-agnostic (eye narrowing is a fraction, others ×10 to a similar scale).
      const signal = targets.reduce((s, r) => s + (a[r] + h[r]) * (r === 'eye' ? 1 : 10), 0);
      return { a, h, signal };
    });
    const idx = selectPeakFrames(per.map((p) => p.signal));
    const cells = {} as Record<CouplingRegion, CouplingCell>;
    for (const r of COUPLING_REGIONS) {
      const affected = median(idx.map((i) => per[i]!.a[r]));
      const healthy = median(idx.map((i) => per[i]!.h[r]));
      const target = targets.includes(r);
      const excess = affected - healthy;
      const th = COUPLING_THRESHOLDS[r];
      const flagged = !target && excess >= th;
      const sig = per.map((p) => p.signal);
      const sync = { affected: pearson(sig, per.map((p) => p.a[r])), healthy: pearson(sig, per.map((p) => p.h[r])) };
      const mild =
        !target && !flagged && excess >= MILD.fraction * th && sync.affected >= MILD.minSync && sync.affected - sync.healthy >= MILD.minSyncLead;
      cells[r] = { affected, healthy, excess, target, flagged, mild, sync };
      if (flagged) result.findings.push({ expression: e, region: r, excess, severity: excess / th });
      if (mild) result.mild!.push({ expression: e, region: r, excess, severity: excess / th });
    }
    result.cells[e] = cells;
    const ta = mean(targets.map((r) => cells[r].affected * (r === 'eye' ? 1 : 10)));
    const th = mean(targets.map((r) => cells[r].healthy * (r === 'eye' ? 1 : 10)));
    if (th > 0.05) result.targetRatio[e] = Math.min(2, ta / th);
  }
  result.findings.sort((x, y) => y.severity - x.severity);
  result.mild!.sort((x, y) => y.severity - x.severity);
  result.status = result.missing.length === 0 ? 'complete' : Object.keys(result.cells).length ? 'incomplete' : 'failed';
  return result;
}

/** Pearson correlation (0 when either series is flat). */
function pearson(x: readonly number[], y: readonly number[]): number {
  const n = Math.min(x.length, y.length);
  if (n < 3) return 0;
  const mx = mean(x.slice(0, n));
  const my = mean(y.slice(0, n));
  let sxy = 0;
  let sxx = 0;
  let syy = 0;
  for (let i = 0; i < n; i++) {
    const [dx, dy] = [x[i]! - mx, y[i]! - my];
    sxy += dx * dy;
    sxx += dx * dx;
    syy += dy * dy;
  }
  return sxx > 1e-12 && syy > 1e-12 ? sxy / Math.sqrt(sxx * syy) : 0;
}
