/**
 * Plain-language findings: turns an assessment into "what is weaker, by how
 * much (%, mm), what to do about it", and a one-line change summary against
 * the previous assessment. Pure; used by the result, home and rehab screens.
 */
import type { AnalysisResult, MovementTaskId } from '../core';
import { REGION_LABEL } from './exercises';

export type FaceRegion = 'forehead' | 'eye' | 'midface' | 'mouth';
export const FACE_REGIONS: readonly FaceRegion[] = ['forehead', 'eye', 'midface', 'mouth'];

/** The assessment task that measures each region. */
export const REGION_TASK: Record<FaceRegion, MovementTaskId> = {
  forehead: 'brow',
  eye: 'eyeClose',
  midface: 'snarl',
  mouth: 'smile',
};

const ACTION: Record<FaceRegion, string> = {
  forehead: '눈썹을 올릴 때',
  eye: '눈을 감을 때',
  midface: '코를 찡그릴 때',
  mouth: '웃을 때',
};

export interface Finding {
  region: FaceRegion;
  /** Affected-side movement as % of the healthy side (capped at 100). */
  pct: number;
  /** Excursion in mm per side, when metric. */
  mm: { affected: number; healthy: number } | null;
  /** Short evidence, e.g. "웃을 때 건강한 쪽의 43% (2.1 / 4.9 mm)". */
  evidence: string;
}

const round1 = (x: number) => Math.round(x * 10) / 10;

export function regionFinding(a: AnalysisResult, region: FaceRegion): Finding | null {
  const s = a.scores;
  if (!s) return null;
  const pct = s.regional[region];
  const t = a.tasks[REGION_TASK[region]];
  const aff = a.affectedSide;
  const healthy = aff === 'left' ? 'right' : 'left';
  const mm = t?.excursionMm ? { affected: round1(t.excursionMm[aff]), healthy: round1(t.excursionMm[healthy]) } : null;
  const mmText = mm && mm.healthy >= 0.5 ? ` (${mm.affected.toFixed(1)} / ${mm.healthy.toFixed(1)} mm)` : '';
  return { region, pct, mm, evidence: `${ACTION[region]} 건강한 쪽의 ${pct}%${mmText}` };
}

/** Regions ordered weakest first; only those below `below` % (default 90). */
export function findings(a: AnalysisResult | null | undefined, below = 90): Finding[] {
  if (!a?.scores) return [];
  return FACE_REGIONS.map((r) => regionFinding(a, r)!)
    .filter((f) => f.pct < below)
    .sort((x, y) => x.pct - y.pct);
}

export interface SynkFinding {
  task: MovementTaskId;
  /** Region that moves involuntarily (where the stretching / dissociation work is aimed). */
  region: FaceRegion;
  grade: number;
  evidence: string;
}

const SYNK_TEXT: Partial<Record<MovementTaskId, { region: FaceRegion; text: string }>> = {
  smile: { region: 'eye', text: '웃을 때 마비 쪽 눈이 함께 작아집니다' },
  snarl: { region: 'eye', text: '코를 찡그릴 때 마비 쪽 눈이 함께 작아집니다' },
  pucker: { region: 'eye', text: '입을 오므릴 때 마비 쪽 눈이 함께 작아집니다' },
  brow: { region: 'mouth', text: '눈썹을 올릴 때 마비 쪽 입꼬리가 따라 움직입니다' },
  eyeClose: { region: 'mouth', text: '눈을 감을 때 마비 쪽 입꼬리가 따라 움직입니다' },
};

/** Measured synkinesis (involuntary co-movement), strongest first. */
export function synkFindings(a: AnalysisResult | null | undefined): SynkFinding[] {
  if (!a) return [];
  const out: SynkFinding[] = [];
  for (const [task, m] of Object.entries(a.tasks) as [MovementTaskId, NonNullable<AnalysisResult['tasks'][MovementTaskId]>][]) {
    const t = SYNK_TEXT[task];
    if (t && m.synkinesisGrade > 0)
      out.push({ task, region: t.region, grade: m.synkinesisGrade, evidence: `${t.text} (동반운동 ${m.synkinesisGrade}/3)` });
  }
  // One entry per region (the co-moving region is what the exercises target); strongest grade first.
  const merged: SynkFinding[] = [];
  for (const f of out.sort((x, y) => y.grade - x.grade)) {
    const m = merged.find((x) => x.region === f.region);
    if (m) m.evidence += ` · ${f.evidence}`;
    else merged.push({ ...f });
  }
  return merged;
}

/**
 * Smallest difference (%p) reported as a change; smaller ones are within the expected measurement error and read
 * "변화 없음". Provisional until the pilot's same-day repeat assessments give the minimal detectable change.
 */
export const CHANGE_BAND = { overall: 5, region: 10 } as const;

/** Direction of a %p difference, with the measurement-error band applied. */
export const changeDir = (d: number, band: number = CHANGE_BAND.overall): 'up' | 'down' | 'same' =>
  Math.abs(d) < band ? 'same' : d > 0 ? 'up' : 'down';

/** One sentence comparing an assessment with the previous one (null without a previous). */
export function changeSummary(cur: AnalysisResult, prev: AnalysisResult | null | undefined, daysBetween?: number): string | null {
  const c = cur.scores;
  const p = prev?.scores;
  if (!c || !p) return null;
  const d = c.functionIndex - p.functionIndex;
  const when = daysBetween === undefined ? '직전 평가' : daysBetween <= 0 ? '같은 날 직전 평가' : `${daysBetween}일 전 평가`;
  const deltas = FACE_REGIONS.map((r) => ({ r, d: c.regional[r] - p.regional[r] })).sort((x, y) => Math.abs(y.d) - Math.abs(x.d));
  const top = deltas[0]!;
  const head =
    changeDir(d) === 'same'
      ? `${when}와 비교해 변화 없음 (움직임 ${c.functionIndex}%, ${d >= 0 ? '+' : ''}${d}%p는 측정 오차 ±${CHANGE_BAND.overall}%p 안).`
      : `${when}보다 움직임이 ${Math.abs(d)}%p ${d > 0 ? '좋아졌습니다' : '줄었습니다'} (${p.functionIndex} → ${c.functionIndex}%).`;
  const tail =
    changeDir(top.d, CHANGE_BAND.region) !== 'same' ? ` 가장 크게 달라진 곳은 ${REGION_LABEL[top.r]} (${top.d > 0 ? '+' : ''}${top.d}%p)입니다.` : '';
  return head + tail;
}
